llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "Zalcitabine, a nucleoside analog with a cytosine base and dideoxy sugar, had an absolute oral bioavailability of 88% in patients versus IV, supporting high oral bioavailability for nucleoside-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C82"],
      "claim": "Dapagliflozin, a sugar-containing C-glucoside, had an absolute oral bioavailability of 78% (90% CI 73–83%) in healthy subjects, supporting high F for polar glycoside-type molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Tofogliflozin, another C-glucoside, had an absolute oral bioavailability of 97.5% in a human mass-balance/IV microdose study, strongly supporting high F for sugar-bearing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Didanosine, a dideoxypurine nucleoside, showed a sub-20% F of 0.17 under fed conditions, but this reflects acid lability and food effects of the dideoxy purine scaffold, which is not shared by the query's full ribose imidazole carboxamide structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence, including absolute oral bioavailability measurements for nucleoside and sugar-containing analogs, supports F well above 20%. The only sub-20% evidence comes from didanosine under fed/child conditions, whose acid-labile dideoxypurine structure is not representative of the query. Prediction: high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "Didanosine low-F records are condition-specific and may not transfer to the full-ribose imidazole carboxamide query.",
    "Transfer scores are high but do not directly encode structural similarity; species and dose differences remain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

